  values ('b0000000-0000-4000-8000-00000000001a', 26, v_facility_id, v_location_id, 'c0000000-0000-4000-8000-000000000014', 'grooming', 'full_groom', 'pending', 'pending', '2024-06-10T18:00:00.000Z', '2024-06-10T19:00:00.000Z', null, 'f0000000-0000-4000-8000-00003dfc570b', 55, 0, 55, null, null, '{"checkInTime":"14:00","checkOutTime":"15:00","stylistPreference":"Sophie Laurent","notificationEmail":true,"notificationSMS":true,"invoice":{"id":"10026","status":"open","items":[{"name":"Full Groom","unitPrice":55,"quantity":1,"price":55,"staffName":"Sophie Laurent"}],"fees":[],"subtotal":55,"discount":0,"taxRate":0.14975,"taxAmount":8.24,"taxes":[{"name":"GST","rate":0.05,"amount":2.75},{"name":"QST","rate":0.09975,"amount":5.49}],"total":63.24,"depositCollected":0,"remainingDue":63.24,"payments":[]}}'::jsonb)
  on conflict (id) do update set
    status = excluded.status, payment_status = excluded.payment_status, start_at = excluded.start_at, end_at = excluded.end_at, total_cost = excluded.total_cost, details = excluded.details;
end $$;

-- @section sequences
do $$
declare
  v_facility_id uuid;
  v_location_id uuid;
begin
  select id into v_facility_id from public.facilities where legacy_id = '11';
  if v_facility_id is null then
    raise exception 'Demo facility (legacy_id 11) not found. Run supabase/seed/dev-accounts.sql first.';
  end if;
  select id into v_location_id from public.locations where facility_id = v_facility_id and is_primary limit 1;

  -- Advance the identity sequences past the explicit refs above, otherwise
  -- the first row the app inserts collides with a seeded one.
  perform setval(pg_get_serial_sequence('public.clients', 'ref'),  (select max(ref) from public.clients));
  perform setval(pg_get_serial_sequence('public.pets', 'ref'),     (select max(ref) from public.pets));
  perform setval(pg_get_serial_sequence('public.bookings', 'ref'), (select max(ref) from public.bookings));
end $$;

select
  (select count(*) from public.clients)      as clients,
  (select count(*) from public.pets)         as pets,
  (select count(*) from public.bookings)     as bookings,
  (select count(*) from public.booking_pets) as booking_pets;
